CREATE TABLE "ReplicaChange" (seq INTEGER PRIMARY KEY AUTOINCREMENT, operationId TEXT NOT NULL UNIQUE, tableName TEXT NOT NULL, rowKey TEXT NOT NULL, payload TEXT NOT NULL, deleted BOOLEAN NOT NULL DEFAULT false, occurredAt TEXT NOT NULL);
CREATE TABLE "ReplicaRow" (id TEXT PRIMARY KEY NOT NULL, tableName TEXT NOT NULL, body TEXT NOT NULL, pending BOOLEAN NOT NULL DEFAULT false);
CREATE INDEX "ReplicaRow_tableName_pending_idx" ON "ReplicaRow" (tableName,pending);
CREATE TABLE "ReplicaControl" (id INTEGER PRIMARY KEY NOT NULL, suppress INTEGER NOT NULL DEFAULT 0);
INSERT INTO "ReplicaControl" VALUES(1,0);
CREATE TRIGGER "replica_Group_insert" AFTER INSERT ON "Group" WHEN (SELECT suppress FROM ReplicaControl WHERE id=1)=0 BEGIN INSERT INTO ReplicaChange(operationId,tableName,rowKey,payload,deleted,occurredAt) VALUES(lower(hex(randomblob(16))),'Group',json_array(NEW."id"),json_object('id',NEW."id",'name',NEW."name",'avatarUrl',NEW."avatarUrl",'avatarBackground',NEW."avatarBackground",'ownerId',NEW."ownerId",'createdAt',NEW."createdAt",'updatedAt',NEW."updatedAt"),false,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
