CREATE TRIGGER "replica_Attachment_update" AFTER UPDATE ON "Attachment" WHEN (SELECT suppress FROM ReplicaControl WHERE id=1)=0 AND NOT (NEW."id" IS OLD."id" AND NEW."uploaderId" IS OLD."uploaderId" AND NEW."clientRequestId" IS OLD."clientRequestId" AND NEW."chatKind" IS OLD."chatKind" AND NEW."chatId" IS OLD."chatId" AND NEW."stagingKey" IS OLD."stagingKey" AND NEW."objectKey" IS OLD."objectKey" AND NEW."originalName" IS OLD."originalName" AND NEW."contentType" IS OLD."contentType" AND NEW."requestedSize" IS OLD."requestedSize" AND NEW."confirmedSize" IS OLD."confirmedSize" AND NEW."reservedBytes" IS OLD."reservedBytes" AND NEW."etag" IS OLD."etag" AND NEW."sourceEtag" IS OLD."sourceEtag" AND NEW."status" IS OLD."status" AND NEW."createdAt" IS OLD."createdAt" AND NEW."expiresAt" IS OLD."expiresAt" AND NEW."abandonAt" IS OLD."abandonAt" AND NEW."leaseUntil" IS OLD."leaseUntil" AND NEW."leaseToken" IS OLD."leaseToken" AND NEW."stagingDeletedAt" IS OLD."stagingDeletedAt" AND NEW."deleteAfter" IS OLD."deleteAfter" AND NEW."messageId" IS OLD."messageId" AND NEW."groupMessageId" IS OLD."groupMessageId") BEGIN INSERT INTO ReplicaChange(operationId,tableName,rowKey,payload,deleted,occurredAt) VALUES(lower(hex(randomblob(16))),'Attachment',json_array(NEW."id"),(SELECT json_group_object(key,value) FROM json_each(json_object('id',NEW."id",'uploaderId',NEW."uploaderId",'clientRequestId',NEW."clientRequestId",'chatKind',NEW."chatKind",'chatId',NEW."chatId",'stagingKey',NEW."stagingKey",'objectKey',NEW."objectKey",'originalName',NEW."originalName",'contentType',NEW."contentType",'requestedSize',NEW."requestedSize",'confirmedSize',NEW."confirmedSize",'reservedBytes',NEW."reservedBytes",'etag',NEW."etag",'sourceEtag',NEW."sourceEtag",'status',NEW."status",'createdAt',NEW."createdAt",'expiresAt',NEW."expiresAt",'abandonAt',NEW."abandonAt",'leaseUntil',NEW."leaseUntil",'leaseToken',NEW."leaseToken",'stagingDeletedAt',NEW."stagingDeletedAt",'deleteAfter',NEW."deleteAfter",'messageId',NEW."messageId",'groupMessageId',NEW."groupMessageId")) WHERE key IN ('id') OR value IS NOT json_extract(json_object('id',OLD."id",'uploaderId',OLD."uploaderId",'clientRequestId',OLD."clientRequestId",'chatKind',OLD."chatKind",'chatId',OLD."chatId",'stagingKey',OLD."stagingKey",'objectKey',OLD."objectKey",'originalName',OLD."originalName",'contentType',OLD."contentType",'requestedSize',OLD."requestedSize",'confirmedSize',OLD."confirmedSize",'reservedBytes',OLD."reservedBytes",'etag',OLD."etag",'sourceEtag',OLD."sourceEtag",'status',OLD."status",'createdAt',OLD."createdAt",'expiresAt',OLD."expiresAt",'abandonAt',OLD."abandonAt",'leaseUntil',OLD."leaseUntil",'leaseToken',OLD."leaseToken",'stagingDeletedAt',OLD."stagingDeletedAt",'deleteAfter',OLD."deleteAfter",'messageId',OLD."messageId",'groupMessageId',OLD."groupMessageId"), '$.' || key)),false,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER "replica_Attachment_delete" AFTER DELETE ON "Attachment" WHEN (SELECT suppress FROM ReplicaControl WHERE id=1)=0 BEGIN INSERT INTO ReplicaChange(operationId,tableName,rowKey,payload,deleted,occurredAt) VALUES(lower(hex(randomblob(16))),'Attachment',json_array(OLD."id"),json_object('id',OLD."id",'uploaderId',OLD."uploaderId",'clientRequestId',OLD."clientRequestId",'chatKind',OLD."chatKind",'chatId',OLD."chatId",'stagingKey',OLD."stagingKey",'objectKey',OLD."objectKey",'originalName',OLD."originalName",'contentType',OLD."contentType",'requestedSize',OLD."requestedSize",'confirmedSize',OLD."confirmedSize",'reservedBytes',OLD."reservedBytes",'etag',OLD."etag",'sourceEtag',OLD."sourceEtag",'status',OLD."status",'createdAt',OLD."createdAt",'expiresAt',OLD."expiresAt",'abandonAt',OLD."abandonAt",'leaseUntil',OLD."leaseUntil",'leaseToken',OLD."leaseToken",'stagingDeletedAt',OLD."stagingDeletedAt",'deleteAfter',OLD."deleteAfter",'messageId',OLD."messageId",'groupMessageId',OLD."groupMessageId"),true,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER replica_attachment_parent AFTER UPDATE OF messageId ON Attachment
WHEN NEW.messageId IS NOT NULL AND OLD.messageId IS NULL AND (SELECT suppress FROM ReplicaControl WHERE id=1)=0
AND NOT EXISTS(SELECT 1 FROM MutationOperation WHERE entityId=NEW.messageId AND type='message.create')
BEGIN INSERT INTO ReplicaChange(operationId,tableName,rowKey,payload,deleted,occurredAt)
SELECT lower(hex(randomblob(16))), 'Message',json_array(m.id),json_object('id',m."id",'fromUserId',m."fromUserId",'toUserId',m."toUserId",'senderName',m."senderName",'text',m."text",'kind',m."kind",'sentAt',m."sentAt",'editedAt',m."editedAt",'answerId',m."answerId",'answerLabel',m."answerLabel",'answeredAt',m."answeredAt",'clientRequestId',m."clientRequestId",'requestHash',m."requestHash",'replyToId',m."replyToId"),false,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM Message m WHERE m.id=NEW.messageId; END;
INSERT INTO ReplicaChange(operationId,tableName,rowKey,payload,deleted,occurredAt) SELECT lower(hex(randomblob(16))),'Group',json_array(r."id"),json_object('id',r."id",'name',r."name",'avatarUrl',r."avatarUrl",'avatarBackground',r."avatarBackground",'ownerId',r."ownerId",'createdAt',r."createdAt",'updatedAt',r."updatedAt"),false,r.updatedAt FROM "Group" r WHERE 1 ORDER BY r."id";
INSERT INTO ReplicaChange(operationId,tableName,rowKey,payload,deleted,occurredAt) SELECT lower(hex(randomblob(16))),'GroupMember',json_array(r."groupId",r."userId"),json_object('groupId',r."groupId",'userId',r."userId"),false,(SELECT updatedAt FROM "Group" WHERE id=r.groupId) FROM "GroupMember" r WHERE 1 ORDER BY r.seq;
INSERT INTO ReplicaChange(operationId,tableName,rowKey,payload,deleted,occurredAt) SELECT lower(hex(randomblob(16))),'Message',json_array(r."id"),json_object('id',r."id",'fromUserId',r."fromUserId",'toUserId',r."toUserId",'senderName',r."senderName",'text',r."text",'kind',r."kind",'sentAt',r."sentAt",'editedAt',r."editedAt",'answerId',r."answerId",'answerLabel',r."answerLabel",'answeredAt',r."answeredAt",'clientRequestId',r."clientRequestId",'requestHash',r."requestHash",'replyToId',r."replyToId"),false,COALESCE(r.editedAt,r.sentAt) FROM "Message" r WHERE (r.kind!='text' OR r.replyToId IS NOT NULL OR EXISTS(SELECT 1 FROM Attachment a WHERE a.messageId=r.id)) ORDER BY r."id";
INSERT INTO ReplicaChange(operationId,tableName,rowKey,payload,deleted,occurredAt) SELECT lower(hex(randomblob(16))),'GroupMessage',json_array(r."id"),json_object('id',r."id",'groupId',r."groupId",'fromUserId',r."fromUserId",'senderName',r."senderName",'text',r."text",'sentAt',r."sentAt",'editedAt',r."editedAt",'clientRequestId',r."clientRequestId",'requestHash',r."requestHash",'replyToId',r."replyToId"),false,COALESCE(r.editedAt,r.sentAt) FROM "GroupMessage" r WHERE 1 ORDER BY r."id";
INSERT INTO ReplicaChange(operationId,tableName,rowKey,payload,deleted,occurredAt) SELECT lower(hex(randomblob(16))),'ChoiceOption',json_array(r."messageId",r."optionId"),json_object('messageId',r."messageId",'optionId',r."optionId",'label',r."label",'position',r."position"),false,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM "ChoiceOption" r WHERE 1 ORDER BY r."messageId",r."optionId";
INSERT INTO ReplicaChange(operationId,tableName,rowKey,payload,deleted,occurredAt) SELECT lower(hex(randomblob(16))),'MessageReaction',json_array(r."messageId",r."userId"),json_object('messageId',r."messageId",'userId',r."userId",'emoji',r."emoji"),false,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM "MessageReaction" r WHERE NOT EXISTS(SELECT 1 FROM MutationOperation WHERE entityId=r.messageId AND type='message.create') ORDER BY r."messageId",r."userId";
INSERT INTO ReplicaChange(operationId,tableName,rowKey,payload,deleted,occurredAt) SELECT lower(hex(randomblob(16))),'MessageDeletion',json_array(r."messageId",r."userId"),json_object('messageId',r."messageId",'userId',r."userId"),false,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM "MessageDeletion" r WHERE NOT EXISTS(SELECT 1 FROM MutationOperation WHERE entityId=r.messageId AND type='message.create') ORDER BY r."messageId",r."userId";
INSERT INTO ReplicaChange(operationId,tableName,rowKey,payload,deleted,occurredAt) SELECT lower(hex(randomblob(16))),'GroupMessageReaction',json_array(r."messageId",r."userId"),json_object('messageId',r."messageId",'userId',r."userId",'emoji',r."emoji"),false,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM "GroupMessageReaction" r WHERE 1 ORDER BY r."messageId",r."userId";
INSERT INTO ReplicaChange(operationId,tableName,rowKey,payload,deleted,occurredAt) SELECT lower(hex(randomblob(16))),'GroupMessageDeletion',json_array(r."messageId",r."userId"),json_object('messageId',r."messageId",'userId',r."userId"),false,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM "GroupMessageDeletion" r WHERE 1 ORDER BY r."messageId",r."userId";
INSERT INTO ReplicaChange(operationId,tableName,rowKey,payload,deleted,occurredAt) SELECT lower(hex(randomblob(16))),'ReadState',json_array(r."userId",r."chatId"),json_object('userId',r."userId",'chatId',r."chatId",'lastDeliveredAt',r."lastDeliveredAt",'lastReadAt',r."lastReadAt"),false,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM "ReadState" r WHERE EXISTS(SELECT 1 FROM "Group" WHERE id=r.chatId) ORDER BY r."userId",r."chatId";
INSERT INTO ReplicaChange(operationId,tableName,rowKey,payload,deleted,occurredAt) SELECT lower(hex(randomblob(16))),'HiddenConversation',json_array(r."ownerId",r."peerId"),json_object('ownerId',r."ownerId",'peerId',r."peerId",'hiddenAt',r."hiddenAt"),false,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM "HiddenConversation" r WHERE 1 ORDER BY r."ownerId",r."peerId";
INSERT INTO ReplicaChange(operationId,tableName,rowKey,payload,deleted,occurredAt) SELECT lower(hex(randomblob(16))),'Attachment',json_array(r."id"),json_object('id',r."id",'uploaderId',r."uploaderId",'clientRequestId',r."clientRequestId",'chatKind',r."chatKind",'chatId',r."chatId",'stagingKey',r."stagingKey",'objectKey',r."objectKey",'originalName',r."originalName",'contentType',r."contentType",'requestedSize',r."requestedSize",'confirmedSize',r."confirmedSize",'reservedBytes',r."reservedBytes",'etag',r."etag",'sourceEtag',r."sourceEtag",'status',r."status",'createdAt',r."createdAt",'expiresAt',r."expiresAt",'abandonAt',r."abandonAt",'leaseUntil',r."leaseUntil",'leaseToken',r."leaseToken",'stagingDeletedAt',r."stagingDeletedAt",'deleteAfter',r."deleteAfter",'messageId',r."messageId",'groupMessageId',r."groupMessageId"),false,r.createdAt FROM "Attachment" r WHERE 1 ORDER BY r."id";
